def build_export(n, start, edges, all_names, fair, safe_flags, done_flags):
    anames = sorted(all_names)
    idx = {}
    for i in range(len(anames)):
        idx[anames[i]] = i + 1
    wf = []
    sf = []
    for (act, mode) in fair:
        j = idx[act]
        if mode == 'weak':
            wf.append(j)
        else:
            sf.append(j)
    wf.sort()
    sf.sort()
    lines = []
    lines.append('---- MODULE ModelData ----')
    lines.append('EXTENDS Integers, Sequences, FiniteSets')
    lines.append('Nodes == 0..%d' % (n - 1))
    lines.append('Initial == %d' % start)
    if edges:
        eb = []
        for (u, nm, v) in edges:
            eb.append('<<%d, %d, %d>>' % (u, idx[nm], v))
        lines.append('Edges == {' + ', '.join(eb) + '}')
    else:
        lines.append('Edges == {}')
    if anames:
        lines.append('ActionNames == <<' +
                     ', '.join('"%s"' % x for x in anames) + '>>')
    else:
        lines.append('ActionNames == <<>>')
    lines.append('WFIds == {' + ', '.join(str(x) for x in wf) + '}')
    lines.append('SFIds == {' + ', '.join(str(x) for x in sf) + '}')
    lines.append('SafeNodes == {' +
                 ', '.join(str(i) for i in range(n) if safe_flags[i]) + '}')
    lines.append('DoneNodes == {' +
                 ', '.join(str(i) for i in range(n) if done_flags[i]) + '}')
    lines.append('====')
    module = '\n'.join(lines) + '\n'
    config = ('SPECIFICATION Spec\nINVARIANT Safety\nPROPERTY Termination\n'
              'CHECK_DEADLOCK FALSE\n')
    return {'module': module, 'config': config}


